<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { deleteExperiment, downloadExperimentExport, getExperiment, getExperiments } from '@/api/ml'
import type { Experiment } from '@/types/ml'
import { utc } from '@/utils/typhoon'
const rows=ref<Experiment[]>([]), detail=ref<Experiment>(), modelType=ref(''), status=ref(''), loading=ref(false)
async function load(){loading.value=true;rows.value=await getExperiments({model_type:modelType.value||undefined,status:status.value||undefined});loading.value=false}
async function open(row:Experiment){detail.value=await getExperiment(row.id)}
async function remove(row:Experiment){await ElMessageBox.confirm(`确定删除实验“${row.name}”及其模型文件吗？此操作不可恢复。`,'二次确认',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await deleteExperiment(row.id);ElMessage.success('实验已删除');detail.value=undefined;await load()}
onMounted(load)
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>实验记录</h2><p>训练配置、模型文件、真实评估和可追溯数据版本</p></div><div><el-button @click="downloadExperimentExport('csv')">导出 CSV</el-button><el-button @click="downloadExperimentExport('xlsx')">导出 Excel</el-button></div></div><el-card shadow="never"><div class="inline-controls"><el-select v-model="modelType" clearable placeholder="全部模型" @change="load"><el-option v-for="m in ['persistence','ridge','lstm','gru']" :key="m" :value="m" :label="m.toUpperCase()"/></el-select><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option v-for="s in ['succeeded','failed','cancelled','interrupted']" :key="s" :value="s" :label="s"/></el-select></div><el-table :data="rows" @row-click="open"><el-table-column prop="name" label="实验" min-width="210"/><el-table-column prop="model_type" label="模型" width="100"/><el-table-column prop="quality_profile" label="质量规则" width="100"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="测试 MAE" width="110"><template #default="{row}">{{row.metrics?.test?.overall?.mae?.toFixed(3)??'—'}}</template></el-table-column><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{utc(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button type="danger" link @click.stop="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="detail" width="760" title="实验详情"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="实验ID">{{detail.id}}</el-descriptions-item><el-descriptions-item label="数据版本">{{detail.dataset_version}}</el-descriptions-item><el-descriptions-item label="模型">{{detail.model_type.toUpperCase()}}</el-descriptions-item><el-descriptions-item label="设备">{{detail.device}}</el-descriptions-item><el-descriptions-item label="训练开始">{{utc(detail.started_at)}}</el-descriptions-item><el-descriptions-item label="训练结束">{{utc(detail.finished_at)}}</el-descriptions-item><el-descriptions-item label="模型文件" :span="2">{{detail.model?.model_path}}</el-descriptions-item></el-descriptions><pre class="json-block">{{JSON.stringify(detail.config,null,2)}}</pre></template></el-dialog></section></template>
